import React, { useEffect, useRef, useState } from 'react';
import type { Node } from '../core/model.js';
import { rpc } from './state/rpc-client.js';
import { runWriteBack, writeBackPhaseLabel, type WriteBackPhase } from './jsx-writeback-run.js';

/*
 * "写回源码" for layers generated by a .tsx component: lists the visual-edit overrides,
 * marks which ones are literal (can go into the JSX source) and which are driven by an
 * expression or by flex/grid layout (they stay overrides), and applies the verified plan
 * through the normal preflight/apply path (one undo).
 */
type PropRow = { id: string; prop: string; status: string; reason?: string };
type Plan = {
  unchanged?: boolean;
  summary?: { written: number; kept: number; file?: string };
  props?: PropRow[];
  candidate?: unknown;
  apply?: unknown;
};
const statusLabel: Record<string, [string, string]> = {
  written: ['可写回', '属性是字面量或缺省，写入 .tsx 后清除覆盖'],
  computed: ['表达式', '属性由表达式计算（如 remap/springTo），保留为覆盖'],
  layout: ['布局', 'flex/grid 布局计算的位置/尺寸，保留为覆盖；请改 style'],
  'changed-output': ['保留', '写成字面量会改变画面（布局或父组件计算），保留为覆盖'],
  'non-literal-value': ['非字面量', '覆盖值不是数字/字符串/布尔，保留为覆盖'],
  spread: ['展开属性', '元素使用 {...props}，无法安全插入，保留为覆盖'],
  'no-target': ['未找到', '源码中没有字面量 id 的元素（可能在别的文件），保留为覆盖'],
  ambiguous: ['重复 id', '多个元素使用同一 id，保留为覆盖'],
  excluded: ['未选', ''],
};

export function JsxWriteBack({
  owner,
  sceneId,
  selectedId,
  ids,
  revision,
  onError,
}: {
  owner: Node;
  sceneId: string;
  /** Generated node selected inside the component (limits the list), if any. Local id. */
  selectedId?: string;
  /** Override ids to list (the selected child and its descendants); default: all. */
  ids?: string[];
  revision?: string;
  onError: (message: string) => void;
}) {
  const [plan, setPlan] = useState<Plan>(),
    [phase, setPhase] = useState<WriteBackPhase>('idle'),
    [elapsed, setElapsed] = useState(0),
    [done, setDone] = useState<string>();
  const busy = phase !== 'idle';
  const overrides = Object.keys(owner.overrides ?? {}).length;
  const scoped = ids?.length
    ? ids
    : selectedId && owner.overrides?.[selectedId]
      ? [selectedId]
      : undefined;
  const request = { sceneId, nodeId: owner.id, ...(scoped ? { ids: scoped } : {}) };
  const live = useRef(true);
  useEffect(() => {
    live.current = true;
    return () => {
      live.current = false;
    };
  }, []);
  // A different component (or a different selected child) clears the last result message; a
  // new revision does not, because our own apply produces one. Keyed on the selection, not on
  // the override list: a successful write-back empties that list.
  useEffect(() => setDone(undefined), [owner.id, sceneId, selectedId]);
  useEffect(() => {
    let current = true;
    setPlan(undefined);
    if (!overrides) return;
    rpc('jsxWriteBackPlan', { ...request, delivery: 'inline' })
      .then((value) => current && setPlan(value as Plan))
      .catch((e) => current && onError((e as Error).message));
    return () => {
      current = false;
    };
    // Re-plan when the project revision or the selection changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [owner.id, sceneId, scoped?.join('|'), revision, overrides]);
  useEffect(() => {
    if (!busy) return;
    const started = performance.now(),
      timer = setInterval(() => setElapsed(Math.round((performance.now() - started) / 1000)), 500);
    setElapsed(0);
    return () => clearInterval(timer);
  }, [busy]);
  // The commit reaches the panel through the live project state, sometimes before the RPC
  // response: once the overrides it wrote are gone at a new revision, the write-back is done.
  const pending = useRef<{ revision?: string; overrides: number; message?: string }>(undefined);
  useEffect(() => {
    const p = pending.current;
    if (phase !== 'applying' || !p?.message || revision === p.revision || overrides >= p.overrides)
      return;
    pending.current = undefined;
    setDone(p.message);
    setPhase('idle');
  }, [phase, revision, overrides]);
  if (!owner.component?.endsWith('.tsx')) return null;
  const rows = (plan?.props ?? []).filter((r) => r.status !== 'excluded'),
    writable = rows.filter((r) => r.status === 'written').length;
  const apply = async () => {
    setDone(undefined);
    try {
      pending.current = { revision, overrides };
      const result = await runWriteBack(rpc, request, (next) => live.current && setPhase(next), (summary) => {
        pending.current = {
          revision,
          overrides,
          message: `已写入 ${summary.written ?? 0} 项到 ${summary.file ?? owner.component}`,
        };
      });
      pending.current = undefined;
      if (live.current && result.written !== undefined)
        setDone(`已写入 ${result.written} 项到 ${result.file ?? owner.component}`);
    } catch (e) {
      onError((e as Error).message);
    } finally {
      if (live.current) setPhase('idle');
    }
  };
  return (
    <div className="jsx-writeback" data-testid="jsx-writeback">
      <p className="jsx-writeback-hint">
        画面上的调整先作为稳定 ID 覆盖保存；字面量属性可以写回 <code>{owner.component}</code>，画面不变，一步撤销。
      </p>
      {!overrides ? (
        <p className="jsx-writeback-empty">此组件没有覆盖可写回。</p>
      ) : busy && !plan ? (
        <p className="jsx-writeback-empty">{writeBackPhaseLabel[phase]}</p>
      ) : !plan ? (
        <p className="jsx-writeback-empty">正在检查覆盖…</p>
      ) : (
        <ul className="jsx-writeback-list" aria-label="覆盖属性">
          {rows.map((r) => {
            const [label, tip] = statusLabel[r.status] ?? [r.status, r.reason ?? ''];
            return (
              <li key={r.id + r.prop} data-status={r.status} title={r.reason ?? tip}>
                <span className="jsx-writeback-id">{r.id.split('/').at(-1)}</span>
                <span className="jsx-writeback-prop">{r.prop}</span>
                <span className="jsx-writeback-badge" data-kind={r.status === 'written' ? 'literal' : 'override'}>
                  {label}
                </span>
              </li>
            );
          })}
        </ul>
      )}
      <div className="jsx-writeback-actions">
        <button
          className="primary"
          disabled={busy || !writable}
          aria-busy={busy}
          onClick={() => void apply()}
          title={writable ? `把 ${writable} 项字面量覆盖写入源码` : '没有可写回的字面量覆盖'}
        >
          {busy ? `${writeBackPhaseLabel[phase]}${elapsed ? ` ${elapsed}s` : ''}` : `写回源码${writable ? ` (${writable})` : ''}`}
        </button>
        {rows.length > writable && (
          <span className="jsx-writeback-kept">{rows.length - writable} 项保留为覆盖</span>
        )}
      </div>
      {done && <p className="jsx-writeback-done">{done}</p>}
    </div>
  );
}
